SELECT * FROM device_template
WHERE device_id = #{deviceId}
ORDER BY create_time DESC

SELECT * FROM device_template
WHERE device_id = #{deviceId}
AND template_type = #{templateType}
ORDER BY create_time DESC

SELECT * FROM device_template
WHERE device_id = #{deviceId}
AND template_type = #{templateType}
AND is_default = 1
LIMIT 1
